def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    cr, cc = next((r, c) for r in range(h) for c in range(w) if grid[r][c] == 3)

    # Build nested square spiral bands around the 3. The alternating
    # two-cell spacing leaves the characteristic gaps between bands.
    for radius in range(1, max(h, w) + 1):
        top, bottom = cr - radius, cr + radius
        left, right = cc - radius, cc + radius
        if 0 <= top < h:
            for c in range(max(0, left), min(w, right + 1)):
                if c != left + 1 and out[top][c] != 2:
                    out[top][c] = 3
        if 0 <= bottom < h:
            for c in range(max(0, left), min(w, right + 1)):
                if c != right - 1 and out[bottom][c] != 2:
                    out[bottom][c] = 3
        if 0 <= left < w:
            for r in range(max(0, top), min(h, bottom + 1)):
                if r != bottom - 1 and out[r][left] != 2:
                    out[r][left] = 3
        if 0 <= right < w:
            for r in range(max(0, top), min(h, bottom + 1)):
                if r != top + 1 and out[r][right] != 2:
                    out[r][right] = 3
    return out
